-- 005: the REAL menu, from the cafe's menu boards (2026-10-13). Already applied to the live project.
-- Replaces the 002 sample menu: sample items are switched off (active=false), not deleted, so old orders still read.
-- Descriptions follow the brand book: plain comma lists, sides as a second short sentence.

begin;
update items set active=false, updated_at=now() where active;
update categories set sort=1, name='{"en": "Hot coffee", "es": "Café caliente", "fr": "Cafés chauds", "de": "Heißer Kaffee", "it": "Caffè caldi", "nl": "Warme koffie", "he": "קפה חם", "nb": "Varm kaffe", "pt": "Café quente"}'::jsonb, station='bar', togo_charge=5, active=true where name->>'en'='Coffee';
update categories set sort=2, name='{"en": "Iced coffee", "es": "Café helado", "fr": "Cafés glacés", "de": "Eiskaffee", "it": "Caffè freddi", "nl": "IJskoffie", "he": "קפה קר", "nb": "Iskaffe", "pt": "Café gelado"}'::jsonb, station='bar', togo_charge=5, active=true where name->>'en'='Iced drinks';
update categories set sort=3, name='{"en": "Smoothies", "es": "Batidos", "fr": "Smoothies", "de": "Smoothies", "it": "Frullati", "nl": "Smoothies", "he": "שייקים", "nb": "Smoothies", "pt": "Vitaminas"}'::jsonb, station='bar', togo_charge=5, active=true where name->>'en'='Smoothies';
update categories set sort=4, name='{"en": "Juice, water and soda", "es": "Jugos, agua y refrescos", "fr": "Jus, eau et sodas", "de": "Saft, Wasser und Softdrinks", "it": "Succhi, acqua e bibite", "nl": "Sap, water en frisdrank", "he": "מיצים, מים ומשקאות קלים", "nb": "Juice, vann og brus", "pt": "Sucos, água e refrigerantes"}'::jsonb, station='bar', togo_charge=5, active=true where name->>'en'='Drinks';
update categories set sort=5, name='{"en": "Breakfast", "es": "Desayuno", "fr": "Petit-déjeuner", "de": "Frühstück", "it": "Colazione", "nl": "Ontbijt", "he": "ארוחת בוקר", "nb": "Frokost", "pt": "Café da manhã"}'::jsonb, station='kitchen', togo_charge=15, active=true where name->>'en'='Breakfast';
update categories set sort=7, name='{"en": "Lunch", "es": "Almuerzo", "fr": "Déjeuner", "de": "Mittagessen", "it": "Pranzo", "nl": "Lunch", "he": "ארוחת צהריים", "nb": "Lunsj", "pt": "Almoço"}'::jsonb, station='kitchen', togo_charge=15, active=true where name->>'en'='Lunch';
update items set description = '{"en": "Fresh greens and whatever veg came in this morning.", "es": "Hojas verdes y las verduras frescas que llegaron hoy.", "fr": "Salade verte et les légumes arrivés ce matin.", "de": "Frisches Grün und das Gemüse, das heute Morgen kam.", "it": "Insalata fresca e le verdure arrivate stamattina.", "nl": "Verse sla en de groenten die vanochtend binnenkwamen.", "he": "עלים ירוקים וירקות טריים שהגיעו הבוקר.", "nb": "Friskt grønt og grønnsakene som kom i morges.", "pt": "Folhas verdes e os legumes que chegaram hoje de manhã."}'::jsonb
  where active and name->>'en' = 'House veggie salad';
update items set description = '{"en": "Fresh greens and whatever veg came in this morning. Topped with chicken.", "es": "Hojas verdes y las verduras frescas que llegaron hoy. Con pollo.", "fr": "Salade verte et les légumes arrivés ce matin. Avec du poulet.", "de": "Frisches Grün und das Gemüse, das heute Morgen kam. Mit Hähnchen.", "it": "Insalata fresca e le verdure arrivate stamattina. Con pollo.", "nl": "Verse sla en de groenten die vanochtend binnenkwamen. Met kip.", "he": "עלים ירוקים וירקות טריים שהגיעו הבוקר. עם עוף.", "nb": "Friskt grønt og grønnsakene som kom i morges. Med kylling.", "pt": "Folhas verdes e os legumes que chegaram hoje de manhã. Com frango."}'::jsonb
  where active and name->>'en' = 'House veggie salad with chicken';
commit;
